begin;

with input_items as (
  select *
  from jsonb_to_recordset($seed_json$[]$seed_json$::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    aliases text[],
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.aliases, '{}'::text[]) as aliases,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset($seed_json$[{"id": "2944684f-d2a0-5b7e-a641-f657ff223841", "feature_slug": "proposal-writing", "title": "W2. Use Journey Walkthroughs As The Core Unit", "content": "The core unit of a proposal section is the journey walkthrough: follow a user, transaction, operator, or data object through the system step by step.\n\nPattern:\n\n```\n1. Name the touchpoint or feature.\n2. Describe the starting state: who, where, what they are doing.\n3. Walk through each step: what the user does, what the system does.\n4. Show the end state: what the user sees, what the system recorded.\n5. Add a diagram or flow that mirrors the walkthrough.\n```\n\nExample:\n\n```\nCustomer arrives at the fuel station.\nStaff enters the transaction on the POS.\nThe POS sends the transaction to Rocket through middleware.\nRocket checks member identity, earn rules, and duplicate-prevention rules.\nRocket returns the points result to the POS.\nThe EDC receipt prints the earned points before the customer leaves.\n```\n\nThe text and diagram should tell the same story from different angles. Text gives the walkthrough; the diagram makes the sequence scannable.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w2-use-journey-walkthroughs-as-the-core-unit", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w2-use-journey-walkthroughs-as-the-core-unit", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "8bde2f37ed2c700118f42d0198c4880a0d484686d0297e9a8ea0760227153ee2", "truncated": false}, "is_active": true}, {"id": "2ab32b2a-aad2-5795-89dd-f8dfc528ca9e", "feature_slug": "proposal-writing", "title": "W3. Present Options With Honest Trade-Offs, Then Recommend", "content": "When multiple implementation approaches exist, show the options and compare them across dimensions the reader actually cares about.\n\nThen make a recommendation.\n\nPattern:\n\n```\nOptions table -> recommendation -> reasoning that references the table dimensions\n```\n\nExample dimensions:\n\n| Option | Security | Complexity | Customer Journey | Best For |\n|---|---|---|---|---|\n| Portal entry | Low | Low | Works with any payment method | Backup scenarios |\n| POS integration | Medium | High | Instant points with OTP | Full-service stations |\n| Sub-merchant EDC | High | High | Card-only | High-volume merchants |\n\nGood recommendation:\n\n> For Merchant On-us, we recommend leveraging existing payment infrastructure through acquirer integration. It has higher setup complexity, but it reduces manual transaction-entry risk and gives the cleanest audit trail.\n\nDo not hide the recommendation in a footnote. A proposal should show the option space, then demonstrate judgment.\n\nUse option tables only when the choice is real: security tolerance, technical capacity, rollout complexity, operational process, or budget. Do not create a comparison table for every minor decision.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w3-present-options-with-honest-trade-offs-then-recommend", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w3-present-options-with-honest-trade-offs-then-recommend", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "563846ddec4f082b58d77f686eb2d15d411359caf170d5b3b43f6baf4ef37c84", "truncated": false}, "is_active": true}, {"id": "f116e0eb-ee37-59fc-b1d5-b69d2981e64a", "feature_slug": "proposal-writing", "title": "W4. Adapt Pyramid Structure To Platform Proposals", "content": "In proposals, the pyramid is not only \"recommendation first, evidence below.\" It is:\n\n> What the platform does first, then how each part works.\n\nExample:\n\n```\nOverview: The platform supports earn and burn across five touchpoints\n    Touchpoint 1: Fuel stations\n        Integration architecture\n        Customer journey - staff-assisted\n        Customer journey - app-initiated\n        Security and duplicate prevention\n    Touchpoint 2: Merchant On-us\n        Portal-entry option\n        POS-integration option\n        Sub-merchant EDC option\n        Recommended path and trade-offs\n    Touchpoint 3: Merchant NFR\n    Touchpoint 4: Online store\n    Touchpoint 5: Rewards\n    Summary: implementation matrix\n```\n\nThe shared rule from `CORE_WRITING_PRINCIPLES.md` still applies: every child section must directly elaborate its parent, and every peer section must be grouped by the same dimension.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w4-adapt-pyramid-structure-to-platform-proposals", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w4-adapt-pyramid-structure-to-platform-proposals", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "e9edca414b204621673996de237f4d2081ebc2156b0d29fb1ae43b126a1aef1a", "truncated": false}, "is_active": true}, {"id": "37e1d235-5fdd-54ee-ad56-7900f2fd9245", "feature_slug": "proposal-writing", "title": "W5. Use SCQA For Section Introductions", "content": "SCQA works best at the section level in proposals.\n\n| Element | In a proposal section |\n|---|---|\n| Situation | What part of the system this section covers |\n| Complication | What makes this part complex or worth detailing |\n| Question | What the reader needs to understand |\n| Answer | What this section will walk through |\n\nExample:\n\n> This section covers the core earn and burn flows across fuel stations, merchant transactions, online purchases, and rewards. These flows require different integration paths, security checks, and customer journeys, so the section maps each touchpoint separately before summarizing the recommended implementation model.\n\nNo broad market preamble. No generic value claim. Just orient the reader to what this section covers and why the detail matters.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w5-use-scqa-for-section-introductions", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w5-use-scqa-for-section-introductions", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "63001807ed21a55ca520d60b7a3efb6ff34f10e1edacd91593376a850be46231", "truncated": false}, "is_active": true}, {"id": "e1a13030-f6a1-5a09-b09a-de3b9fa9c35c", "feature_slug": "proposal-writing", "title": "W6. Apply MECE To Proposal Scope", "content": "Use `CORE_WRITING_PRINCIPLES.md` for the general MECE rule. In proposals, stress-test MECE against the operational scope the reader expects.\n\nCommon proposal CE checks:\n\n| Level | Proposal-specific test |\n|---|---|\n| Ecosystem overview | Does the overview cover every touchpoint where a customer interacts with the platform? |\n| Each touchpoint | Does it cover architecture, customer journey, operational flow, and options if multiple approaches exist? |\n| Earn and burn | Are both directions mapped for every relevant touchpoint? |\n| Operations | Can the reader see who configures, monitors, reviews, and fixes the flow after launch? |\n\nThe most common proposal failure is covering the happy path while skipping edge cases and unsupported scenarios.\n\n**Constraints the customer raised must be addressed somewhere.** If the customer's TOR or Q&A asks about a constraint (channel limitation, SLA, data residency), address it. The appropriate place is wherever that constraint affects the customer's decision — not in a generic Limitations block. A constraint that lives in a relevant subsection is far more credible than a list at the end.\n\nDo not add a limitations block as a default coverage item. See `CORE_WRITING_PRINCIPLES.md §12` for the updated rule on when limitations are appropriate.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w6-apply-mece-to-proposal-scope", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w6-apply-mece-to-proposal-scope", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "1c1f2ef07c65c7e2ae2b4111c1790a57a55eaf4eb0131af1e991354f84d5b585", "truncated": false}, "is_active": true}, {"id": "95e96935-dbca-55ca-be44-55a92a7d93e8", "feature_slug": "proposal-writing", "title": "W7. Cross-Reference Dependencies Without Repeating Them", "content": "Platform features depend on each other. A proposal should make those dependencies visible without duplicating entire walkthroughs.\n\nGood:\n\n> Many earn and burn flows depend on the Merchant Portal for partner registration, reward management, and transaction review. The Merchant Portal is covered in the next section.\n\nUse cross-references for:\n\n- Shared portals or admin tools.\n- Shared customer profiles.\n- Shared security controls.\n- Shared integration middleware.\n- Shared reporting or reconciliation flows.\n\nDo not re-explain the same feature in full under every section that touches it.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w7-cross-reference-dependencies-without-repeating-them", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w7-cross-reference-dependencies-without-repeating-them", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "55e521d16671c3e3d8a73e3262fd6a016bdbe69f3b7fbe0976df2f59b19ee083", "truncated": false}, "is_active": true}, {"id": "4a38fd0d-1f51-58f9-bb40-0d29a57f6c5d", "feature_slug": "proposal-writing", "title": "W8. Use Layered Proposal Depth", "content": "A proposal should let different readers stop at different depths.\n\nProposal depth pattern:\n\n```\nLevel 1: Overview table or ecosystem diagram\nLevel 2: Architecture diagram per major component\nLevel 3: Sequence diagram or journey walkthrough per flow\nLevel 4: Configuration, edge cases, security, and operational detail\nLevel 5: Summary matrix across components, options, or touchpoints\n```\n\nExecutives should be able to read the overview and summary tables. Technical and operational readers should be able to find implementation detail without wading through positioning copy.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w8-use-layered-proposal-depth", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w8-use-layered-proposal-depth", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "a5a051f1fb88c7a310ab05381bc7fec7ad73ac80021bf51cd4b9c576a26af181", "truncated": false}, "is_active": true}, {"id": "c02e38a9-f18c-53ad-870e-bae62a402d12", "feature_slug": "proposal-writing", "title": "W9. Follow The Reader's Natural Question Flow", "content": "A platform proposal should follow the evaluation sequence of someone trying to understand a system:\n\n```\nExecutive summary: what does this platform do?\n    -> Core journeys: how do customers interact with it?\n        -> Portal and tools: how do operators manage it?\n            -> Technical architecture: how is it built?\n                -> Integrations: how does it connect to our systems?\n                    -> Migration: how do we get from here to there?\n                        -> Operations and support: what happens after launch?\n```\n\nEvery section should answer the reader's next natural question. If a section jumps from high-level benefit to implementation detail and back again, the reader has to rebuild the structure themselves.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/PROPOSAL_WRITING_PRINCIPLES.md#w9-follow-the-reader-s-natural-question-flow", "metadata": {"genre": "proposal", "source_file": "PROPOSAL_WRITING_PRINCIPLES.md", "section_anchor": "w9-follow-the-reader-s-natural-question-flow", "parent_section": "Section 4 — Writing", "feature_slug": "proposal-writing", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f5aaf1248e06f88b1e7c898c02e868cf1d8283b236a2abf430d9c9a3f80f26b7", "truncated": false}, "is_active": true}, {"id": "ec74ccd4-8a1d-5f76-a1e0-2892d4840eff", "feature_slug": "sales-slides", "title": "1. Lead With The Buyer, Not Rocket", "content": "The customer is the hero. Rocket is the guide and system.\n\nBad:\n\n> Rocket is an AI-powered Loyalty CRM with comprehensive features.\n\nBetter:\n\n> Your marketing team can turn every purchase into data, every member into an engaged customer, and every customer signal into an automated next action.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#1-lead-with-the-buyer-not-rocket", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "1-lead-with-the-buyer-not-rocket", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "34e70a06be77c02b4409eb67f371f003488eba757b78e29d310b2c4e4db5d0dd", "truncated": false}, "is_active": true}, {"id": "e3ec387d-44b0-51eb-9be9-53034d30071f", "feature_slug": "sales-slides", "title": "10. Use Matrices To Prove Scope", "content": "When claiming broad coverage, show the complete map instead of saying \"comprehensive.\"\n\nExample: omnichannel point collection\n\n| | Brand-owned | Third-party |\n|---|---|---|\n| Online | Website / Shopify | Shopee / Lazada / TikTok Shop |\n| Offline | POS | Receipt upload / QR scan |\n\nThis proves the scope in one glance.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#10-use-matrices-to-prove-scope", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "10-use-matrices-to-prove-scope", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "677e5c6993c5302999264719d7957d73c17bf9e226894ffe8274edaf298f774a", "truncated": false}, "is_active": true}, {"id": "d62bd18b-ed4a-57f2-9580-0f93e5714dd9", "feature_slug": "sales-slides", "title": "11. Avoid Fake Balance", "content": "MECE does not mean every section needs the same number of bullets or slides.\n\nIf AI activation needs three slides and rewards needs one, that is fine. Let the system's real complexity determine the space.\n\nDo not pad simple topics for symmetry.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#11-avoid-fake-balance", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "11-avoid-fake-balance", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5d9e05641f5a7eba66f68ded621663f66bd403a181047f7aa03588fc516608fa", "truncated": false}, "is_active": true}, {"id": "25c5f05b-c789-5762-8292-4d95ef5ce6ea", "feature_slug": "sales-slides", "title": "12. Pass The 5-Second Feature Test", "content": "Every feature slide should answer two questions immediately:\n\n1. What feature is this?\n2. Why would a marketer, operator, or finance stakeholder care?\n\nIf the buyer has to decode a clever phrase before knowing the feature, the slide fails. Prefer plain feature names plus specific copy over abstract benefit language.\n\nWeak:\n\n> Tiers turn progress into a reason to return.\n\nStronger:\n\n> Tiers & Benefits\n\nSupporting copy:\n\n> Set tier rules by points, spend, orders, or tickets. Rocket evaluates the highest eligible tier first, so high performers can skip levels automatically.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#12-pass-the-5-second-feature-test", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "12-pass-the-5-second-feature-test", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "8ee5b9e10993338df41da0e3dcb57872b762f29378e6b0adbc7766edfac5ad77", "truncated": false}, "is_active": true}, {"id": "84b14a66-a4fc-500a-a8e0-94fc9a19fd25", "feature_slug": "sales-slides", "title": "13. Use Mental Validation For Feature Scope", "content": "When a slide claims a feature has broad scope, prove it with recognizable components at the same abstraction level. Buyers scan feature slides like a checklist.\n\nWeak:\n\n> Flexible reward configuration.\n\nStrong:\n\n> Eligibility, points price, stock, limits, expiry, promo-code pools, and fulfillment are configured on the reward record.\n\nRules:\n\n- Keep peer items at the same level.\n- Keep grammar consistent.\n- Use a qualifier only when the next line proves it with examples.\n- Use checklist detail only when the slide's job is feature-scope validation. If the slide's job is to explain a concept or operating model, use higher-level parts instead of long feature inventories.\n- Put the concept before the inventory. Data fields, feature objects, and product terms are proof examples, not the main message.\n\nWeak:\n\n> See member tier, points, purchases, redemptions, form answers, and support tickets.\n\nStronger:\n\n> View all customer data in one place, then use the AI customer brief to understand the customer and push the optimal next action instantly. Examples include purchases, points, redemptions, and support history.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#13-use-mental-validation-for-feature-scope", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "13-use-mental-validation-for-feature-scope", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5daf320a1f2248e49991a896576d07febeb8c25440a4e3148d0d69acefa9b01d", "truncated": false}, "is_active": true}, {"id": "61e0db42-6188-5aff-af9f-2b408ec6ea7f", "feature_slug": "sales-slides", "title": "14. Preserve Product Vocabulary, Explain It For Marketers", "content": "CRM Knowledge MCP is the source of truth for feature vocabulary. Do not replace product concepts with looser synonyms if the original term is the product model. Keep the term, then explain it in language a marketer, operator, or CRM owner would understand.\n\nGood hierarchy:\n\n> MCP feature vocabulary → feature model → marketer-understandable explanation → visual support\n\nBad:\n\n> Missions are challenges with rewards.\n\nBetter:\n\n> Missions let marketers set goals for member actions such as purchases, referrals, forms, check-ins, or points earned. Each goal can have outcomes such as points, tickets, rewards, or milestone progress.\n\nDo not rename concepts:\n\n- `Missions`, `goals`, `outcomes`, `progress`, `claim`, `limits`, and `milestones` should not become generic `challenges` and `rewards`.\n- `Display Blocks` should not become `app blocks`.\n- `Earn Factors` should not become generic `bonus rules` unless used only as supporting explanation.\n- `AI Decisioning` should preserve `Act / Wait / Skip`.\n\nAvoid backend/internal terms unless the buyer needs them: `BFF`, `RPC`, `UUID`, `cache`, table names, function names, source IDs, and implementation object names. Keep technical precision in the concept, not in the implementation detail.\n\nWeak:\n\n> Target blocks by persona or guest status, link them to rewards, missions, tiers, or personas, then publish through cached app reads.\n\nStronger:\n\n> Display Blocks let marketers choose which sections appear on the member home screen, such as profile cards, banners, rewards, missions, tier progress, and quick actions. Blocks can be shown to all members or only to selected personas.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#14-preserve-product-vocabulary-explain-it-for-marketers", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "14-preserve-product-vocabulary-explain-it-for-marketers", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "ef8069005a0e3a26eca3f528a397dd4d2735b4d4ea90a16c3b9f53316e845692", "truncated": false}, "is_active": true}, {"id": "f982f209-5e5e-5feb-bb21-bd9ec47eddc2", "feature_slug": "sales-slides", "title": "15. Show Motion, Not Labels", "content": "Abstract labels are hard to picture. Show what happens.\n\nWeak:\n\n> Unified customer profile across all channels.\n\nStrong:\n\n> A customer buys from Shopify, Shopee, POS, or distributor. Rocket records the purchase, calculates points, and adds the activity to one customer profile.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#15-show-motion-not-labels", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "15-show-motion-not-labels", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f186dbef4d9ea8c5c89e90f9321afae6b5af0d8859ce42c726c03bee6dad8ac2", "truncated": false}, "is_active": true}, {"id": "f4c43d7a-0cdd-5b6b-b3cc-dad0be515afc", "feature_slug": "sales-slides", "title": "16. Describe Features Through Operational Utility", "content": "Describe the task the user can perform, not the abstract module name. Use verbs from the buyer's daily work: set rules, launch campaigns, review redemptions, compare segments, approve claims, assign rewards, inspect outcomes.\n\nWeak:\n\n> Campaign management.\n\nStrong:\n\n> Create a mission from purchases, form submissions, referrals, or check-ins; Rocket tracks progress and reward claims automatically.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#16-describe-features-through-operational-utility", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "16-describe-features-through-operational-utility", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "47de625892971dece6f5be5ee258c1208acf507765bdb8f7dd89d7abe04450c1", "truncated": false}, "is_active": true}, {"id": "c829beb9-52ac-59f7-8ff0-94dd5ae557c7", "feature_slug": "sales-slides", "title": "17. Describe AI By The Decision It Makes", "content": "Do not sell AI as a label. Name the decision or action it performs.\n\nWeak:\n\n> AI-powered personalization.\n\nStrong:\n\n> AI detects churn risk, chooses the right offer, and sends it before the customer disappears.\n\nRocket AI should be framed as activation:\n\n> Analyze → Decide → Act\n\nNot:\n\n> Analyze → Dashboard → Human still does the work", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#17-describe-ai-by-the-decision-it-makes", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "17-describe-ai-by-the-decision-it-makes", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b9b0796ed75c58c69568029ab51b22aefefba933d592bac05d466f767effb507", "truncated": false}, "is_active": true}, {"id": "327cfb64-be4a-56d7-af4f-849734ccdd5c", "feature_slug": "sales-slides", "title": "18. Proof Comes Before Deep Feature Detail", "content": "Before showing many features, give the buyer a reason to trust the system.\n\nUse:\n\n- Relevant customer logo\n- One metric\n- Before / after snapshot\n- Concrete implementation result\n- Product screenshot that proves the claim\n\nAvoid generic logo dumping if it does not support the buyer's decision.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#18-proof-comes-before-deep-feature-detail", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "18-proof-comes-before-deep-feature-detail", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "95c119ba7033bb652808d6faa492c027dc9e52475e65a8a9de846529d8b1669e", "truncated": false}, "is_active": true}, {"id": "f93f8ab8-668a-5fd0-83ba-38c96d482358", "feature_slug": "sales-slides", "title": "19. Features Must Map To Buyer Pain", "content": "Every feature slide should answer:\n\n1. What marketing problem does this solve?\n2. What action does the team take?\n3. What does Rocket automate or make visible?\n4. What proof or example makes it credible?\n\nExample format:\n\n> Problem → Rocket behavior → Marketing outcome → Proof\n\nFor compact feature slides, use this simpler structure:\n\n> Feature name → concrete configuration scope → what happens in the member/admin experience → why the team cares", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#19-features-must-map-to-buyer-pain", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "19-features-must-map-to-buyer-pain", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "bca1917afba4800d7362efd5fd6b0e2cc7312bf9c41011efeffc61461cd7ec2d", "truncated": false}, "is_active": true}, {"id": "f8065271-f49f-5bd3-81f1-928f3314c5db", "feature_slug": "sales-slides", "title": "2. Use The Right Category Altitude", "content": "For marketing teams, default to `Loyalty CRM`.\n\nUse:\n\n- `Loyalty CRM` for marketing leaders evaluating tools.\n- `Loyalty program` or `ระบบสะสมแต้ม` for practical/search-friendly contexts.\n- `Agentic B2C CRM` for vision, leadership, PR, investor, and brand-level moments.\n\nDo not lead cold buyers with high-altitude language before they understand what the product is.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#2-use-the-right-category-altitude", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "2-use-the-right-category-altitude", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f96ff3d9740774bc1b017cb5ae8a670e03b80a8df368cf5c6a12d8e1c05aed46", "truncated": false}, "is_active": true}, {"id": "c425427a-1213-512e-821f-5205e6bb5a65", "feature_slug": "sales-slides", "title": "20. Name The Cost Of Doing Nothing", "content": "Marketing teams need urgency, not just product understanding.\n\nUseful cost-of-inaction angles:\n\n- Customers buy once and disappear.\n- Members exist but are inactive.\n- Campaigns depend on blanket promotions.\n- First-party data remains fragmented.\n- Competitors personalize while the brand still sends the same offer to everyone.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#20-name-the-cost-of-doing-nothing", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "20-name-the-cost-of-doing-nothing", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "fc7247b18e42207de27f5744f08813f11fbe484eef74338e6c608e5b07025378", "truncated": false}, "is_active": true}, {"id": "a8b88e07-8cdb-5ce5-bbfd-868c7258ffec", "feature_slug": "sales-slides", "title": "21. Handle Objections Inside The Deck", "content": "Do not wait for objections to appear after the presentation.\n\nAddress:\n\n- Setup time\n- Integration effort\n- Campaign complexity\n- Data quality\n- Team workload\n- Measurement and ROI\n- Security / permissions\n- Budget and stakeholder approval\n\nUse specific answers, not reassurance.\n\nWeak:\n\n> Easy implementation.\n\nStrong:\n\n> Launch path: demo → configure earn rules and rewards → connect LINE / purchase channels → launch first campaign in 2 weeks.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#21-handle-objections-inside-the-deck", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "21-handle-objections-inside-the-deck", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "2fa08d10c5bcf34c74f3d64fea53ce7f829d55afb0f5480bb19540422f5c5a51", "truncated": false}, "is_active": true}, {"id": "0b157f90-3d5b-5c72-87c9-f6d19e22295e", "feature_slug": "sales-slides", "title": "22. Make The Deck Champion-Forwardable", "content": "The deck should still make sense when the marketing champion forwards it to CEO, finance, IT, or procurement.\n\nRules:\n\n- No presenter-only references like \"as mentioned.\"\n- Headlines carry the message.\n- Acronyms are defined once.\n- Proof points are clear without verbal explanation.\n- Implementation and next steps are concrete.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#22-make-the-deck-champion-forwardable", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "22-make-the-deck-champion-forwardable", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "102bf75fec237a04efc993872d1a7d89862ffc363ec12498f93668b3978446e4", "truncated": false}, "is_active": true}, {"id": "48ec71eb-551d-5f47-9ec4-c4aa7bf51502", "feature_slug": "sales-slides", "title": "23. Use Diagrams For System Understanding", "content": "Use diagrams when the slide explains:\n\n- Journey\n- Workflow\n- Integration\n- Data movement\n- Before / after process\n- Role handoff\n\nDo not use diagrams as decoration. The diagram must make the system easier to understand than text would.\n\nDo not describe the diagram unless it needs interpretation. Good visual-heavy slides use text to state the implication, decision, or model behind the visual:\n\n- Timeline visual: headline names the journey or system loop.\n- Architecture visual: headline names the operating model.\n- Product screenshot: headline names the buyer task or proof point.\n- Diagram labels: short nouns or verbs only; the body carries the meaning.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#23-use-diagrams-for-system-understanding", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "23-use-diagrams-for-system-understanding", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b120e87388d08c431494bf7883655ea1c527b60d296144798cd39ae6a77beeda", "truncated": false}, "is_active": true}, {"id": "0fea6d49-c791-5714-8753-889d7fdceca0", "feature_slug": "sales-slides", "title": "24. Keep Text Short, But Not Vague", "content": "Short is good only if it remains specific.\n\nApply the one-breath test to feature headlines. If the headline cannot be read in one short breath, it is usually trying to do the work that belongs in the body copy.\n\nWeak:\n\n> Flexible campaigns.\n\nStrong:\n\n> Create missions, referrals, check-ins, and tier challenges without developer work.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#24-keep-text-short-but-not-vague", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "24-keep-text-short-but-not-vague", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "e2fab615f5249d81e3e9a50b453bdc1060c4da01a3f11e6af5bcefe9fef99f49", "truncated": false}, "is_active": true}]$seed_json$::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
